package au.aumanet.app;
import org.json.*;import java.util.*;
/** Bounded read-only observations. RF sample age remains unknown. */
final class GroupRadioSignal {
 static JSONArray checked(JSONArray input,long now,String verification)throws Exception{if(input==null||input.length()>2)throw new IllegalArgumentException("Unbounded signal observations");JSONArray result=new JSONArray();Set<String> nodes=new HashSet<>();long revision=-1;String a="",b="",firstDirection="",firstReceiverPhone="",firstTransmitterPhone="";boolean firstMapped=false;for(int i=0;i<input.length();i++){JSONObject raw=input.getJSONObject(i);String receiver=id(raw,"receiverNodeId",32,false),sender=id(raw,"transmitterNodeId",32,false),run=id(raw,"sourceRun",32,false),observation=id(raw,"observationId",64,true);if(receiver.equals(sender)||!nodes.add(receiver))throw new IllegalArgumentException("Signal direction conflict");long config=number(raw,"configRevision"),age=number(raw,"readAgeMs");if(config<1||revision!=-1&&revision!=config)throw new IllegalArgumentException("Signal configuration differs");revision=config;if(i==0){a=receiver;b=sender;}else if(!a.equals(sender)||!b.equals(receiver))throw new IllegalArgumentException("Signal pair differs");String status=raw.getString("status"),direction=raw.getString("direction");if(!Arrays.asList("available","unavailable","unsupported").contains(status)||!Arrays.asList("ap-to-station","station-to-ap").contains(direction)||raw.opt("authenticated")!=Boolean.TRUE||raw.opt("sampleAgeKnown")!=Boolean.FALSE||!"associated-ap-last-known".equals(raw.getString("kind")))throw new IllegalArgumentException("Signal provenance differs");if(i==0)firstDirection=direction;else if(direction.equals(firstDirection))throw new IllegalArgumentException("Signal directions repeat");boolean mapped=raw.has("receiverPhoneId")||raw.has("transmitterPhoneId");String receiverPhone=mapped?id(raw,"receiverPhoneId",64,true):"",transmitterPhone=mapped?id(raw,"transmitterPhoneId",64,true):"";if(mapped&&receiverPhone.equals(transmitterPhone))throw new IllegalArgumentException("Signal phones repeat");if(i==0){firstMapped=mapped;firstReceiverPhone=receiverPhone;firstTransmitterPhone=transmitterPhone;}else if(mapped!=firstMapped||mapped&&(!firstReceiverPhone.equals(transmitterPhone)||!firstTransmitterPhone.equals(receiverPhone)))throw new IllegalArgumentException("Signal phone pair differs");JSONObject value=new JSONObject().put("status",status).put("authenticated",true).put("verification",verification).put("receiverNodeId",receiver).put("transmitterNodeId",sender).put("sourceRun",run).put("observationId",observation).put("kind","associated-ap-last-known").put("direction",direction).put("readAgeMs",age).put("sampleAgeKnown",false).put("observedElapsedMs",now).put("configRevision",config);if(mapped)value.put("receiverPhoneId",receiverPhone).put("transmitterPhoneId",transmitterPhone);if(verification.equals("owner-relayed"))value.put("relayAgeMs",0);if(status.equals("available")){Object rawRssi=raw.get("rssiDbm");if(!(rawRssi instanceof Number))throw new IllegalArgumentException("Invalid RSSI");long rssi=((Number)rawRssi).longValue();if(((Number)rawRssi).doubleValue()!=rssi)throw new IllegalArgumentException("Invalid RSSI");if(rssi < -127||rssi > -1||!direction.equals("ap-to-station"))throw new IllegalArgumentException("Unavailable RSSI");value.put("rssiDbm",rssi);}else if(raw.has("rssiDbm"))throw new IllegalArgumentException("Unexpected RSSI");result.put(value);}return result;}
 static JSONArray age(JSONArray values,long elapsed,long now)throws Exception{if(elapsed<0)return new JSONArray();JSONArray copy=new JSONArray(values.toString());for(int i=0;i<copy.length();i++){JSONObject value=copy.getJSONObject(i);long before=value.getLong("readAgeMs");if(before>GroupNamePolicy.MAX_REVISION-elapsed)return new JSONArray();value.put("readAgeMs",before+elapsed).put("observedElapsedMs",now);if(value.optString("verification").equals("owner-relayed")){long relay=value.getLong("relayAgeMs");if(relay>GroupNamePolicy.MAX_REVISION-elapsed)return new JSONArray();value.put("relayAgeMs",relay+elapsed);}}return copy;}
 static JSONArray merge(JSONArray old,long elapsed,JSONArray next,long now)throws Exception{JSONArray prior=age(old,elapsed,now);JSONArray result=checked(next,now,"owner-relayed");for(int i=0;i<result.length();i++){JSONObject value=result.getJSONObject(i);for(int j=0;j<prior.length();j++){JSONObject p=prior.getJSONObject(j);if(p.getString("receiverNodeId").equals(value.getString("receiverNodeId"))&&p.getString("sourceRun").equals(value.getString("sourceRun"))&&p.getString("observationId").equals(value.getString("observationId"))&&p.getLong("configRevision")==value.getLong("configRevision")&&Objects.equals(p.opt("receiverPhoneId"),value.opt("receiverPhoneId"))&&Objects.equals(p.opt("transmitterPhoneId"),value.opt("transmitterPhoneId"))){value.put("readAgeMs",Math.max(value.getLong("readAgeMs"),p.getLong("readAgeMs")));value.put("relayAgeMs",p.optLong("relayAgeMs",0));}}}return result;}
 private static String id(JSONObject o,String key,int length,boolean upper)throws Exception{String value=o.getString(key);if(!value.matches((upper?"[A-F0-9]":"[a-f0-9]")+"{"+length+"}"))throw new IllegalArgumentException("Invalid signal identity");return value;}
 private static long number(JSONObject o,String key)throws Exception{Object raw=o.get(key);if(!(raw instanceof Number))throw new IllegalArgumentException("Invalid signal bound");double d=((Number)raw).doubleValue();long n=((Number)raw).longValue();if(!Double.isFinite(d)||d!=n||n<0||n>GroupNamePolicy.MAX_REVISION)throw new IllegalArgumentException("Invalid signal bound");return n;}
}
